
const createDiv = function (text, color, bgColor) {
    const div = document.createElement('div')
    console.log(div)

    div.className = 'main'
    div.id = 'div-main-1'
    div.setAttribute('title', "generated title")
    div.style.backgroundColor = bgColor
    div.style.color = color
    div.style.padding = '10px'

    // div.innerText = "This is the first div that is being generated by external js"
    const addText = document.createTextNode(text)
    div.appendChild(addText)
    document.body.appendChild(div)
}

createDiv(text="This is the first div that is being generated by external js", color='yellow', bgColor='red')
createDiv("Learning JavaScript DOM", "white", "green")

